package com.v2v.smartsystem.safety;

/**
 * Encapsulates an active safety warning generated by the V2V collision avoidance engine.
 */
public class WarningEvent {

    public enum Severity {
        INFO,
        WARNING,
        CRITICAL
    }

    private final String warningId;
    private final String title;
    private final String description;
    private final Severity severity;
    private final String sourceVehicleId;
    private final double distanceMeters;
    private final long timestamp;

    public WarningEvent(String warningId, String title, String description, Severity severity,
                        String sourceVehicleId, double distanceMeters) {
        this.warningId = warningId;
        this.title = title;
        this.description = description;
        this.severity = severity;
        this.sourceVehicleId = sourceVehicleId;
        this.distanceMeters = distanceMeters;
        this.timestamp = System.currentTimeMillis();
    }

    public String getWarningId() { return warningId; }
    public String getTitle() { return title; }
    public String getDescription() { return description; }
    public Severity getSeverity() { return severity; }
    public String getSourceVehicleId() { return sourceVehicleId; }
    public double getDistanceMeters() { return distanceMeters; }
    public long getTimestamp() { return timestamp; }
}
